contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 v) public payable {
        require(true);

        IOracleProvider.OracleVersion memory r;
        bool reverted;
        try c.atVersion(v) returns (IOracleProvider.OracleVersion memory res) {
            r = res;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            IOracleProvider.OracleVersion memory again;
            bool reverted2;
            try c.atVersion(v) returns (IOracleProvider.OracleVersion memory res2) {
                again = res2;
                reverted2 = false;
            } catch {
                reverted2 = true;
            }

            assert(reverted2 == reverted && again.version == r.version && again.timestamp == r.timestamp && again.price == r.price);
        } else {
            assert(reverted);
        }
    }

    receive() external payable {}
}

