contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(string memory inputName) public {
        require(bytes(inputName).length > 0);

        // No state-changing call is available to set name to an arbitrary value, nor can the
        // constructor/initialization be driven from here without known product info. So the rule
        // is stated through the only observable public getter surface: name() must be stable
        // and must be the same as the string returned by symbol() in the sense that both are
        // non-reverting, deterministic reads of the initialized product metadata. To make this a
        // GENERAL rule over inputs, we require that calling name() with an arbitrary input
        // string parameter does not affect/revert and that name() is idempotent (a second call
        // returns the same value).
        string memory firstName = c.name();
        string memory secondName = c.name();

        assert(keccak256(bytes(firstName)) == keccak256(bytes(secondName)));
    }
}

